from pybricks.hubs import PrimeHub
from pybricks.parameters import Axis, Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up all devices.
prime_hub = PrimeHub(top_side=Axis.Z, front_side=Axis.X)
Mt_1 = Motor(Port.F, Direction.COUNTERCLOCKWISE)
motor_2 = Motor(Port.D, Direction.CLOCKWISE)
Att_MTR = Motor(Port.A, Direction.CLOCKWISE)
Att_MTR_2 = Motor(Port.B, Direction.CLOCKWISE)
drive_base_2 = DriveBase(Mt_1, motor_2, 86, 132)


# The main program starts here.
drive_base_2.use_gyro(True)
drive_base_2.straight(200)
drive_base_2.turn(-90)
drive_base_2.straight(690)
# at the mission but not doing it
drive_base_2.turn(-90)
drive_base_2.straight(115)
drive_base_2.turn(-20)
Att_MTR_2.run_angle(500, 1000)
Att_MTR.stop()
drive_base_2.straight(-300)
drive_base_2.turn(-100)
drive_base_2.settings(straight_speed=1000)
drive_base_2.straight(-900)
prime_hub.speaker.beep(659, 125)
prime_hub.speaker.beep(659, 125)
prime_hub.speaker.beep(50000, 125)
prime_hub.speaker.beep(659, 128)
prime_hub.speaker.beep(50000, 167)
prime_hub.speaker.beep(523, 125)
prime_hub.speaker.beep(659, 125)
prime_hub.speaker.beep(50000, 125)
prime_hub.speaker.beep(784, 125)
prime_hub.speaker.beep(50000, 375)
prime_hub.speaker.beep(392, 125)
prime_hub.speaker.beep(50000, 375)
